function RightSection(
    imageURL,
    productName,
    productDescription,
    learnMore,
    kite, Connect
) {
    return (

        <div className="container mt-5">
            <div className="row">
                <div className="col-6">
                    <h1>{productName}</h1>
                    <p>{productDescription}</p>
                    <div>
                        <a href=" " >{learnMore}</a>
                    </div>
                </div>
                <div className="col-6"></div>
            </div>
        </div>
    );
}

export default RightSection;
